inputs = ['bv', 'cwd', 'wfziy', 'kw', 'bbjvg']
outputs = ['bv', 'chd', 'hfzihe', 'vwh', 'bbjvvwdf']

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings"""
    # Simple approach: find first differing character position
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if we're replacing or inserting/deleting
            if len(s_in) == len(s_out):
                return (s_in[i], s_out[i], i)
            elif len(s_in) > len(s_out):
                # Deletion
                return (s_in[i], '', i)
            else:
                # Insertion
                return ('', s_out[i], i)

    # If we reach here, one string is prefix of the other
    if len(s_in) > len(s_out):
        return (s_in[min_len], '', min_len)
    else:
        return ('', s_out[min_len], min_len)

changed = [(1, 'cwd', 'chd'), (2, 'wfziy', 'hfzihe'), (3, 'kw', 'vwh'), (4, 'bbjvg', 'bbjvvwdf')]

for idx, inp, out in changed:
    old_sub, new_sub, pos = find_minimal_edit(inp, out)
    print(f"Pair {idx}: '{inp}' -> '{out}' | Change: '{old_sub}' -> '{new_sub}' at position {pos}")

